<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>{{ $partner->name }} | Partner Performance</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet"><style>
:root{--navy:#102a43;--ink:#16324f;--muted:#6b7c93;--teal:#07877e;--mint:#dff6f1;--line:#dbe6ef;--paper:#f5f8fb;--gold:#f0b84b}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}.shell{max-width:1220px;margin:0 auto;padding:30px 26px 70px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.brand{display:flex;align-items:center;gap:12px;font-family:'Space Grotesk',sans-serif;font-weight:700;letter-spacing:-.02em}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--navy);color:#fff;font-size:15px}.private{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;font-weight:600;background:#fff;border:1px solid var(--line);border-radius:30px;padding:9px 13px}.private i{color:var(--teal)}.hero{position:relative;overflow:hidden;border-radius:26px;background:linear-gradient(120deg,#102a43 0%,#164c62 58%,#087f78 100%);color:#fff;padding:42px 46px;box-shadow:0 18px 50px rgba(16,42,67,.18)}.hero:after{content:'';position:absolute;width:310px;height:310px;border-radius:50%;right:-80px;top:-130px;background:rgba(255,255,255,.09);box-shadow:-60px 210px 0 30px rgba(255,255,255,.045)}.eyebrow{position:relative;z-index:1;text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:700;color:#a8e7dd}.hero h1{position:relative;z-index:1;margin:12px 0 7px;font:700 42px/1.05 'Space Grotesk',sans-serif;letter-spacing:-.04em}.hero p{position:relative;z-index:1;margin:0;color:#d6f4ef;font-size:15px}.hero-meta{position:relative;z-index:1;margin-top:24px;display:flex;gap:18px;flex-wrap:wrap;color:#c4e3e5;font-size:13px}.hero-meta span{display:inline-flex;align-items:center;gap:7px}.hero-meta strong{color:#fff}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.stat,.panel{background:#fff;border:1px solid rgba(219,230,239,.9);border-radius:18px;box-shadow:0 8px 30px rgba(28,61,86,.06)}.stat{padding:22px}.stat-label{color:var(--muted);font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.08em}.stat-value{font:700 30px 'Space Grotesk',sans-serif;margin-top:10px;color:var(--navy)}.stat-sub{font-size:12px;color:var(--muted);margin-top:5px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:34px 0 14px}.section-head h2{font:700 25px 'Space Grotesk',sans-serif;letter-spacing:-.03em;margin:0}.section-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.updated{font-size:12px;color:var(--muted)}.campaign{overflow:hidden;margin-bottom:18px}.campaign-head{display:flex;gap:22px;padding:22px;border-bottom:1px solid var(--line)}.campaign-art{width:150px;height:94px;border-radius:13px;object-fit:cover;background:linear-gradient(135deg,#dff6f1,#e9eff8);flex:0 0 150px}.campaign-info{flex:1;min-width:0}.campaign-title{font:700 20px 'Space Grotesk',sans-serif;margin:0 0 5px}.campaign-description{color:var(--muted);font-size:13px;margin:0;max-width:680px}.campaign-badges{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.badge{display:inline-flex;padding:6px 9px;border-radius:20px;font-size:11px;font-weight:700}.badge-live{background:var(--mint);color:#087f78}.badge-budget{background:#fff5dc;color:#9a6a14}.campaign-progress{padding:20px 22px;background:#fbfdff}..progress-row{display:flex;justify-content:space-between;gap:15px;font-size:12px;color:var(--muted);margin-bottom:8px}.progress-row strong{color:var(--navy)}.bar{height:9px;background:#e8eef3;border-radius:20px;overflow:hidden}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--teal),#39b7a3);border-radius:20px;min-width:0}.task-title{padding:20px 22px 5px;font:700 16px 'Space Grotesk',sans-serif}.task-table{width:100%;border-collapse:collapse}.task-table th,.task-table td{padding:13px 22px;text-align:left;border-bottom:1px solid #edf2f6;font-size:13px}.task-table th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.07em}.task-table tr:last-child td{border-bottom:0}.task-name{font-weight:700}.task-type{display:block;color:var(--muted);font-size:11px;margin-top:3px}.mode{font-size:11px;color:var(--muted)}.mode-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--teal);margin-right:5px}.mode-review .mode-dot{background:var(--gold)}.number{font-weight:700;color:var(--navy)}.footer{margin-top:30px;color:#8294a6;font-size:12px;text-align:center}@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}.hero{padding:32px 26px}.hero h1{font-size:34px}.campaign-head{align-items:flex-start}.task-table{min-width:700px}.table-wrap{overflow:auto}.shell{padding:20px 15px 50px}}@media(max-width:520px){.stats{grid-template-columns:1fr 1fr;gap:10px}.stat{padding:16px}.stat-value{font-size:24px}.campaign-head{display:block}.campaign-art{width:100%;height:150px;margin-bottom:16px}.topbar{margin-bottom:18px}}
</style></head><body><main class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">B</span><span>Blockrium Partner Insights</span></div><div class="private"><i class="fa-solid fa-lock"></i> Private reporting link</div></header><section class="hero"><div class="eyebrow">Partner performance report</div><h1>{{ $partner->name }}</h1><p>Read-only campaign analytics and reward distribution overview.</p><div class="hero-meta"><span><strong>{{ $campaigns->count() }}</strong> campaigns</span><span><strong>{{ number_format($summary['brc_distributed'], 4) }}</strong> BRC distributed</span><span><i class="fa-solid fa-shield-halved"></i> Verified reporting</span></div></section><section class="stats"><div class="stat"><div class="stat-label">Total clicks</div><div class="stat-value">{{ number_format($summary['clicks']) }}</div><div class="stat-sub">All campaign links</div></div><div class="stat"><div class="stat-label">Unique users</div><div class="stat-value">{{ number_format($summary['unique_users']) }}</div><div class="stat-sub">Authenticated participants</div></div><div class="stat"><div class="stat-label">Claims</div><div class="stat-value">{{ number_format($summary['claims']) }}</div><div class="stat-sub">Rewards issued</div></div><div class="stat"><div class="stat-label">BRC distributed</div><div class="stat-value">{{ number_format($summary['brc_distributed'], 4) }}</div><div class="stat-sub">Across all campaigns</div></div></section><div class="section-head"><div><h2>Campaign performance</h2><p>Task-level results, conversion, and budget utilization.</p></div><span class="updated">Live read-only view</span></div>@forelse($campaigns as $campaign)<article class="panel campaign"><div class="campaign-head">@if($campaign->image_url)<img class="campaign-art" src="{{ $campaign->image_url }}" alt="{{ $campaign->title }} banner">@else<div class="campaign-art"></div>@endif<div class="campaign-info"><h3 class="campaign-title">{{ $campaign->title }}</h3><p class="campaign-description">{{ $campaign->description ?: 'Partner campaign performance overview.' }}</p><div class="campaign-badges"><span class="badge badge-live">{{ ucfirst($campaign->status) }}</span>@if($campaign->budget_amount !== null)<span class="badge badge-budget">{{ number_format($campaign->metrics['budget_remaining'], 4) }} BRC remaining</span>@endif</div></div></div><div class="campaign-progress">@if($campaign->budget_amount !== null) @php $budget = (float) $campaign->budget_amount; $distributed = (float) $campaign->metrics['brc_distributed']; $percent = $budget > 0 ? min(100, ($distributed / $budget) * 100) : 0; @endphp<div class="progress-row"><span>Reward allocation used</span><strong>{{ number_format($distributed, 4) }} / {{ number_format($budget, 4) }} BRC</strong></div><div class="bar"><span style="width:{{ $percent }}%"></span></div>@else<div class="progress-row"><span>Reward allocation</span><strong>Flexible campaign budget</strong></div>@endif</div><div class="task-title">Task performance</div><div class="table-wrap"><table class="task-table"><thead><tr><th>Task</th><th>Mode</th><th>Clicks</th><th>Claims</th><th>BRC</th><th>Conversion</th></tr></thead><tbody>@forelse($campaign->metrics['tasks'] as $task)<tr><td><span class="task-name">{{ $task['title'] }}</span><span class="task-type">{{ ucwords(str_replace('_', ' ', $task['task_type'])) }} &middot; {{ number_format($task['reward_amount'], 4) }} {{ $task['reward_label'] }}</span></td><td><span class="mode {{ $task['completion_mode'] === 'admin_approval' ? 'mode-review' : '' }}"><span class="mode-dot"></span>{{ $task['completion_mode'] === 'admin_approval' ? 'Admin review' : 'Click & claim' }}</span></td><td class="number">{{ number_format($task['clicks']) }}</td><td class="number">{{ number_format($task['claims']) }}</td><td class="number">{{ number_format($task['brc_distributed'], 4) }}</td><td class="number">{{ number_format($task['conversion_rate'], 2) }}%</td></tr>@empty<tr><td colspan="6" style="color:#8294a6">Tasks will appear here once configured.</td></tr>@endforelse</tbody></table></div></article>@empty<div class="panel" style="padding:38px;text-align:center;color:#6b7c93">No campaigns have been configured yet.</div>@endforelse<footer class="footer">This private dashboard is provided by Blockrium. Metrics are read-only and update as users interact with each campaign.</footer></main></body></html>
